using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Graph.Walks;
internal sealed class WeightedVertexProductsDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "On a connected graph over a commutative group with surjective squaring, symmetric edge weights factor into vertex products exactly when every even closed walk balances. For a bipartite graph over any commutative group, every specified spanning tree gives equivalent simple-cycle and fundamental-cycle tests.",
        H("Weighted Vertex Products and Closed Walks"), Blocks(
            Paragraph(Text("Let V be an arbitrary vertex type, A a commutative group, G a simple graph, and w:Sym2(V)->A symmetric edge weights. For a walk p, alpha(w,p) is List.alternatingProd of its edge-weight list. Every occurrence is retained, including repeated edges and immediate backtracks. The empty walk has value one. Sol(w,G) means that there is b:V->A with b(u)b(v)=w({u,v}) on every edge.")),
            Describe.Lean(DescribeId.Create("even-closed-walks"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Walks/WeightedVertexProducts.vertex_products_iff_even_closed_walks"),
                H("Even Closed Walks Are the Complete Obstruction"),
                StatementSource.FromAuthor(Closed()), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The square map a->aa is assumed surjective and G is connected. Along a walk from u to v, a vertex factorization gives alpha(p)=b(u)b(v)^(-(-1)^length(p)). At a root, either every closed walk is even, and its value can be set to one, or an odd closed walk fixes the square of the root value. Concatenating two odd loops shows that this constraint is independent of the chosen loop. Comparing two root-to-vertex walks through their closed concatenation proves path compatibility. Transporting the root value then constructs all vertex factors."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("bipartite-tree-cycles"),
                DeclarationHandle.Create("D5/S3/Combinatorics/Graph/Walks/WeightedVertexProducts.bipartite_cycle_tree_criteria"),
                H("Simple Cycles and Every Spanning Tree"),
                StatementSource.FromAuthor(Trees()), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("No square-root hypothesis is needed here. The graph is bipartite and T is any specified spanning tree on the same vertices. Tree paths construct vertex factors. A non-tree edge together with the tree path returning to its initial vertex is a fundamental simple cycle. Bipartiteness makes that returning path odd. Balancing its cycle is exactly the missing edge equation. Thus checking all simple cycles, or only the fundamental cycles of any T, is equivalent to Sol(w,G). Connectedness is carried by T.IsTree; no finiteness hypothesis is imposed."))), DescribeRole.Theorem),
            Paragraph(Text("For finite characteristic-two fields, the square-root premise follows from the bijective Frobenius map. In the stabilizer model, n is any odd integer at least three and q is at least two. The replica character is t:Fin(q-1)->ZMod(n); its readout on a party c is t(c) for c<q-1 and zero on the last party. Any coloring col:V->Fin(q) is allowed, and x(u) is that readout at col(u). The field is the intermediate field generated by a primitive nth root zeta inside the algebraic closure of F2. Primitive-root power injection identifies the nonempty character fibers with the lambda fibers. The zero character gives the empty support graph. Stabilizer edge weights are lambda(u)+lambda(v) on the support where this sum is nonzero. Applying the graph criterion to these units requires the exact character-fiber support correspondence. For the fiber mask A(u,v)=0 when the character readouts agree and A(u,v)=Gamma(u,v) otherwise, a solution gives M=B(A mapped into F)B with B=diag(beta). Diagonal invertibility and rank_map_algebraMap at its original QuantumMaxFlowBound owner give rank_F(M)=rank_F2(A). This deduction includes empty principal restrictions. Component rank additivity and any converse to rank equality require separate results.")))));
    private static Formula Closed()
    {
        Formula V=F.Id("V"), A=F.Id("A"), G=F.Id("G"), w=F.Id("w");
        return Disp(All("V", Call("Type"), All("A", Call("Type"),
            Imp(Call("CommGroup", A), All("G", Call("SimpleGraph", V),
                All("w", Call("Function", Call("Sym2", V), A),
                    Imp(Call("SurjectiveSquare", A), Imp(Call("Connected", G),
                        Iff(Call("Sol", w, G), All("u", V,
                            All("p", Call("Walk", G, F.Id("u"), F.Id("u")),
                                Imp(Call("Even", Call("length", F.Id("p"))),
                                    Eq(Call("alpha", w, F.Id("p")), D(1))))))))))))));
    }
    private static Formula Trees()
    {
        Formula V=F.Id("V"), A=F.Id("A"), G=F.Id("G"), w=F.Id("w"), T=F.Id("T");
        return Disp(All("V", Call("Type"), All("A", Call("Type"), Imp(Call("CommGroup", A),
            All("G", Call("SimpleGraph", V), All("w", Call("Function", Call("Sym2", V), A),
                Imp(Call("Colorable", G, D(2)), All("T", Call("SimpleGraph", V),
                    Imp(Call("SubgraphOnSameVertices", T, G), Imp(Call("IsTree", T),
                        And(Iff(Call("Sol", w, G), Call("AllSimpleCyclesBalance", w, G)),
                            Iff(Call("Sol", w, G), Call("AllFundamentalCyclesBalance", w, G, T)))))))))))));
    }
    private static Formula Call(string n, params Formula[] a) => a.Length == 0
        ? new Formula.NamedConstant(FormulaIdentifier.Create(n))
        : new Formula.Apply(new Formula.NamedConstant(FormulaIdentifier.Create(n)), [.. a]);
    private static Formula All(string n, Formula t, Formula b) => new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(n), t, b);
    private static Formula Eq(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(Seq(Open,a,Close), FormulaLogicOperator.And, Seq(Open,b,Close));
    private static Formula Iff(Formula a, Formula b) => new Formula.Logic(Seq(Open,a,Close), FormulaLogicOperator.Iff, Seq(Open,b,Close));
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(Seq(Open,a,Close), FormulaLogicOperator.Implies, Seq(Open,b,Close));
}
